def JamesTreeTest.singleton (S : JamesTreeSegmentFamily) (t : DyadicTreeNode) :
    JamesTreeTest S where
  count := 1
  segment _ := {t}
  allowed _ := S.singleton_allowed t
  disjoint := fun i j hij => (hij (Subsingleton.elim i j)).elim

